// plan.ts
//
// Pure port of blueprint-kit/tools/blueprintlib.py: no I/O, no Worker APIs, so it runs unchanged in tests.
// Behaviour is kept identical to the Python reference on purpose (test/parity.test.ts checks this against
// fixtures generated by the Python code). If you change a rule here, change it in blueprintlib.py too.

import { parse as parseYaml } from "yaml";

export type Dict = Record<string, any>;
export type Cell = Dict & { id: string };

export interface Config {
  project?: string;
  main_branch: string;
  lease_minutes: number;
  max_ci_minutes: number;
  bottleneck_threshold: number;
  critical_lease_minutes: number;
  critical_chain_threshold: number;
  critical_transitive_threshold: number;
  park_max_minutes: number;
  max_attempts: number;
  max_cell_files: number;
  acceptance_timeout_s: number;
  protected_paths: string[];
  owners: Record<string, string>;
}

export const ID_RE = /^C-\d{3,}$/;
export const SUBJECT_RE = /^cell\((C-\d{3,})\)/;
export const BRANCH_RE = /^cell\/(C-\d{3,})$/;
export const RUN_TITLE_RE = /\b(?:gate|preflight)\s+(?:cell\/)?(C-\d{3,})\b/;
export const KINDS = ["implementation", "contract"];
export const CELL_KEYS = ["id", "title", "type", "priority", "lease_minutes", "goal", "inputs", "after", "provides", "read", "allowed_paths", "outputs", "acceptance", "notes", "supersedes"];
export const CELL_TYPES = ["normal", "skeleton", "integration"];
export const DEFAULT_PROTECTED = [
  "cells/**",
  "blueprint.yaml",
  "BLUEPRINT.md",
  "tools/**",
  ".github/**",
  "acceptance/**",
  "docs/decisions.md",
];
export const DEFAULTS = {
  main_branch: "main",
  lease_minutes: 60,
  max_ci_minutes: 45,
  bottleneck_threshold: 4,
  critical_lease_minutes: 15,
  critical_chain_threshold: 3,
  critical_transitive_threshold: 5,
  park_max_minutes: 120,
  max_attempts: 3,
  max_cell_files: 8,
  acceptance_timeout_s: 600,
  protected_paths: [] as string[],
  owners: {} as Record<string, string>,
};

// ---------------------------------------------------------------- python-compat helpers
function pyTruthy(v: unknown): boolean {
  if (v === null || v === undefined || v === false || v === 0 || v === "") return false;
  if (Array.isArray(v)) return v.length > 0;
  if (typeof v === "object") return Object.keys(v as object).length > 0;
  return true;
}

export function pyRepr(v: unknown): string {
  if (v === null || v === undefined) return "None";
  if (typeof v === "string") return `'${v.replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
  if (typeof v === "boolean") return v ? "True" : "False";
  if (typeof v === "number") return String(v);
  return JSON.stringify(v);
}

/** Python's round(): half to even. */
export function pyRound(x: number): number {
  const f = Math.floor(x);
  const d = x - f;
  if (d < 0.5) return f;
  if (d > 0.5) return f + 1;
  return f % 2 === 0 ? f : f + 1;
}

function isStr(x: unknown): x is string {
  return typeof x === "string";
}
function isStrList(v: unknown): v is string[] {
  return Array.isArray(v) && v.every(isStr);
}
function isPosInt(v: unknown): boolean {
  return typeof v === "number" && Number.isInteger(v) && v > 0;
}
function isMapping(v: unknown): v is Dict {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

const BOOL_TAG = "tag:yaml.org,2002:bool";

function yamlLoad(text: string): unknown {
  // YAML 1.1 like PyYAML's safe_load, so a file means the same thing to the CI tools and to this connector.
  // One deliberate deviation from the 1.1 spec, to match PyYAML: a lone `y` or `n` is a string, not a boolean.
  return parseYaml(text, {
    version: "1.1",
    customTags: (tags: any[]) =>
      tags.map((t) => {
        if (t.tag !== BOOL_TAG) return t;
        if (t.test.test("y") && t.test.test("yes")) return { ...t, test: /^(?:[Yy]es|YES|[Tt]rue|TRUE|[Oo]n|ON)$/ };
        if (t.test.test("n") && t.test.test("no")) return { ...t, test: /^(?:[Nn]o|NO|[Ff]alse|FALSE|[Oo]ff|OFF)$/ };
        return t;
      }),
  });
}

// ---------------------------------------------------------------- loading
export function loadConfig(text: string | null | undefined): { cfg: Config; errors: string[] } {
  const errors: string[] = [];
  const cfg: Dict = { ...DEFAULTS, protected_paths: [], owners: {} };
  if (text) {
    let data: unknown;
    try {
      data = yamlLoad(text) ?? {};
    } catch (e) {
      errors.push(`blueprint.yaml: invalid YAML (${String((e as Error).message).split("\n")[0]})`);
      data = {};
    }
    if (isMapping(data)) {
      for (const [k, v] of Object.entries(data)) {
        if (k in DEFAULTS || k === "project") cfg[k] = v;
      }
    } else {
      errors.push("blueprint.yaml: must be a mapping");
    }
  }
  cfg.protected_paths = [...DEFAULT_PROTECTED, ...(Array.isArray(cfg.protected_paths) ? cfg.protected_paths : [])];
  cfg.owners = isMapping(cfg.owners) ? { ...cfg.owners } : {};
  return { cfg: cfg as Config, errors };
}

/** files: file name inside cells/ -> text. Mirrors load_cells (file names matching C-*.yaml, sorted). */
export function loadCells(files: Record<string, string>): { cells: Record<string, Cell>; errors: string[] } {
  const cells: Record<string, Cell> = {};
  const errors: string[] = [];
  const names = Object.keys(files)
    .filter((n) => n.startsWith("C-") && n.endsWith(".yaml"))
    .sort();
  for (const name of names) {
    const stem = name.slice(0, -".yaml".length);
    let data: unknown;
    try {
      data = yamlLoad(files[name]);
    } catch (e) {
      errors.push(`${name}: invalid YAML (${String((e as Error).message).split("\n")[0]})`);
      continue;
    }
    if (!isMapping(data)) {
      errors.push(`${name}: must be a mapping`);
      continue;
    }
    if (data.id !== stem) {
      errors.push(`${name}: id ${pyRepr(data.id)} must equal file name ${pyRepr(stem)}`);
    }
    data.id = stem;
    cells[stem] = data as Cell;
  }
  return { cells, errors };
}

export function slist(cell: Dict, key: string): string[] {
  const v = cell[key];
  return Array.isArray(v) ? v.filter(isStr) : [];
}

export function inputsOf(cell: Dict): Dict[] {
  const v = cell.inputs;
  return Array.isArray(v) ? v.filter(isMapping) : [];
}

/** Cells that must be MERGED before this one may start. */
export function hardDeps(cell: Dict): string[] {
  const deps: unknown[] = inputsOf(cell)
    .filter((i) => i.kind === "implementation")
    .map((i) => i.from);
  deps.push(...slist(cell, "after"));
  const out: string[] = [];
  for (const d of deps) if (isStr(d) && !out.includes(d)) out.push(d);
  return out;
}

export function acceptanceCmds(cell: Dict): string[] {
  const out: string[] = [];
  const v = cell.acceptance;
  for (const a of Array.isArray(v) ? v : []) {
    if (isStr(a) && a.trim()) out.push(a.trim());
    else if (isMapping(a) && isStr(a.cmd) && a.cmd.trim()) out.push(a.cmd.trim());
  }
  return out;
}

// ---------------------------------------------------------------- paths
function norm(p: string): string {
  p = p.trim().replace(/^\.\//, "");
  return p.endsWith("/") ? p + "**" : p;
}

function hasWild(s: string): boolean {
  return /[*?[]/.test(s);
}

function reEscape(ch: string): string {
  return ch.replace(/[.*+?^${}()|[\]\\\/-]/g, "\\$&");
}

export function globRegex(pat: string): RegExp {
  pat = norm(pat);
  let i = 0;
  let out = "";
  while (i < pat.length) {
    if (pat.startsWith("**/", i)) {
      out += "(?:.*/)?";
      i += 3;
    } else if (pat.startsWith("**", i)) {
      out += ".*";
      i += 2;
    } else if (pat[i] === "*") {
      out += "[^/]*";
      i += 1;
    } else if (pat[i] === "?") {
      out += "[^/]";
      i += 1;
    } else {
      out += reEscape(pat[i]);
      i += 1;
    }
  }
  return new RegExp("^" + out + "$", "s");
}

export function matches(path: string, patterns: string[]): boolean {
  return patterns.some((p) => globRegex(p).test(path));
}

/** Port of Python's fnmatch.fnmatchcase for one path segment. */
export function fnmatchCase(name: string, pat: string): boolean {
  let out = "";
  let i = 0;
  while (i < pat.length) {
    const c = pat[i++];
    if (c === "*") out += ".*";
    else if (c === "?") out += ".";
    else if (c === "[") {
      let j = i;
      if (j < pat.length && pat[j] === "!") j++;
      if (j < pat.length && pat[j] === "]") j++;
      while (j < pat.length && pat[j] !== "]") j++;
      if (j >= pat.length) {
        out += "\\[";
      } else {
        let stuff = pat.slice(i, j).replace(/\\/g, "\\\\");
        i = j + 1;
        if (stuff[0] === "!") stuff = "^" + stuff.slice(1);
        else if (stuff[0] === "^") stuff = "\\" + stuff;
        out += `[${stuff}]`;
      }
    } else out += reEscape(c);
  }
  return new RegExp("^" + out + "$", "s").test(name);
}

/** Conservative: true if some path could match both globs. */
export function mayOverlap(a: string, b: string): boolean {
  const A = norm(a).split("/");
  const B = norm(b).split("/");
  const n = Math.min(A.length, B.length);
  for (let k = 0; k < n; k++) {
    const x = A[k];
    const y = B[k];
    if (x === "**" || y === "**") return true;
    const wx = hasWild(x);
    const wy = hasWild(y);
    if (!wx && !wy) {
      if (x !== y) return false;
    } else if (wx && wy) {
      continue; // two different wildcards: cannot rule out, stay conservative
    } else if (!(fnmatchCase(x, y) || fnmatchCase(y, x))) {
      return false;
    }
  }
  return A.length === B.length;
}

export function firstOverlap(pathsA: string[], pathsB: string[]): [string, string] | null {
  for (const pa of pathsA) for (const pb of pathsB) if (mayOverlap(pa, pb)) return [pa, pb];
  return null;
}

// ---------------------------------------------------------------- graph
export function findCycle(graph: Record<string, string[]>): string[] | null {
  const color: Record<string, number> = {};
  for (const n of Object.keys(graph)) color[n] = 0;
  const stack: string[] = [];

  const dfs = (n: string): string[] | null => {
    color[n] = 1;
    stack.push(n);
    for (const m of graph[n]) {
      if (color[m] === 1) return [...stack.slice(stack.indexOf(m)), m];
      if (color[m] === 0) {
        const r = dfs(m);
        if (r) return r;
      }
    }
    stack.pop();
    color[n] = 2;
    return null;
  };

  for (const n of Object.keys(graph)) {
    if (color[n] === 0) {
      const r = dfs(n);
      if (r) return r;
    }
  }
  return null;
}

export function ancestors(graph: Record<string, string[]>): Record<string, Set<string>> {
  const memo: Record<string, Set<string>> = {};
  const f = (n: string): Set<string> => {
    if (!memo[n]) {
      const s = new Set<string>();
      for (const d of graph[n]) {
        s.add(d);
        for (const x of f(d)) s.add(x);
      }
      memo[n] = s;
    }
    return memo[n];
  };
  const out: Record<string, Set<string>> = {};
  for (const n of Object.keys(graph)) out[n] = f(n);
  return out;
}

export function hardGraph(cells: Record<string, Cell>): Record<string, string[]> {
  const out: Record<string, string[]> = {};
  for (const [cid, c] of Object.entries(cells)) {
    out[cid] = hardDeps(c).filter((d) => d in cells && d !== cid);
  }
  return out;
}

/** Topological levels over hard edges. Cells in one level can run in parallel. */
export function waves(cells: Record<string, Cell>): Record<number, string[]> {
  const g = hardGraph(cells);
  const level: Record<string, number> = {};
  const lv = (n: string): number => {
    if (!(n in level)) level[n] = 1 + Math.max(-1, ...g[n].map(lv));
    return level[n];
  };
  const out: Record<number, string[]> = {};
  for (const n of Object.keys(g)) (out[lv(n)] ||= []).push(n);
  for (const k of Object.keys(out)) out[Number(k)].sort();
  return out;
}

/** {cell id: number of cells that must wait for its MERGE (implementation / after edges)}. */
export function directDependents(cells: Record<string, Cell>): Record<string, number> {
  const out: Record<string, number> = {};
  for (const c of Object.keys(cells)) out[c] = 0;
  for (const deps of Object.values(hardGraph(cells))) for (const d of deps) out[d] += 1;
  return out;
}

/** {cell id: number of distinct cells that depend on it, directly or not (implementation / after edges)}. */
export function transitiveDependents(cells: Record<string, Cell>): Record<string, number> {
  const dependents: Record<string, string[]> = {};
  for (const c of Object.keys(cells)) dependents[c] = [];
  for (const [c, ds] of Object.entries(hardGraph(cells))) for (const d of ds) dependents[d].push(c);
  const out: Record<string, number> = {};
  for (const c of Object.keys(cells)) {
    const seen = new Set<string>();
    const stack = [...dependents[c]];
    while (stack.length) {
      const n = stack.pop() as string;
      if (seen.has(n) || n === c) continue;
      seen.add(n);
      stack.push(...dependents[n]);
    }
    out[c] = seen.size;
  }
  return out;
}

// ---------------------------------------------------------------- validation
export function validate(cells: Record<string, Cell>, cfg: Config): { errors: string[]; warnings: string[] } {
  const E: string[] = [];
  const W: string[] = [];
  const ids = new Set(Object.keys(cells));
  if (ids.size === 0) E.push("no cells found");
  const protectedPaths = cfg.protected_paths;

  for (const [cid, c] of Object.entries(cells)) {
    const p = `${cid}: `;
    if (!ID_RE.test(cid)) E.push(p + "id must look like C-001");
    for (const k of Object.keys(c).sort()) {
      if (!CELL_KEYS.includes(k)) E.push(p + `unknown key '${k}' (typo? a misspelt key is silently ignored otherwise)`);
    }
    for (const k of ["title", "goal", "allowed_paths", "outputs", "acceptance"]) {
      if (!pyTruthy(c[k])) E.push(p + `missing '${k}'`);
    }
    for (const k of ["allowed_paths", "outputs", "after", "provides", "read", "supersedes"]) {
      const v = c[k];
      if (v !== null && v !== undefined && !isStrList(v)) E.push(p + `'${k}' must be a list of strings`);
    }
    const t = c.type === undefined ? "normal" : c.type;
    if (!CELL_TYPES.includes(t)) E.push(p + `type must be one of ${pyListRepr(CELL_TYPES)}`);
    if ("priority" in c && !(Number.isInteger(c.priority) || typeof c.priority === "boolean")) {
      E.push(p + "priority must be an integer");
    }
    if ("lease_minutes" in c && !isPosInt(c.lease_minutes)) E.push(p + "lease_minutes must be a positive integer");
    if (pyTruthy(c.acceptance) && acceptanceCmds(c).length === 0) {
      E.push(p + "acceptance needs at least one command ('cmd: ...')");
    }

    const inputs = Array.isArray(c.inputs) ? c.inputs : [];
    inputs.forEach((i: unknown, n: number) => {
      const q = p + `inputs[${n}]: `;
      if (!isMapping(i)) {
        E.push(q + "must be a mapping");
        return;
      }
      const src = i.from;
      const kind = i.kind;
      if (!ids.has(src)) E.push(q + `unknown cell ${pyRepr(src)}`);
      else if (src === cid) E.push(q + "a cell cannot depend on itself");
      if (!KINDS.includes(kind)) E.push(q + `kind must be one of ${pyListRepr(KINDS)}`);
      if (!String(pyTruthy(i.contract) ? i.contract : "").trim()) {
        E.push(q + "contract text required (the agent must not need to read the provider's code)");
      }
      if (kind === "contract" && ids.has(src) && src !== cid && slist(cells[src], "provides").length === 0) {
        E.push(q + `${src} has no 'provides' to consume as a contract`);
      }
    });
    for (const a of slist(c, "after")) {
      if (!ids.has(a)) E.push(p + `after: unknown cell ${pyRepr(a)}`);
      else if (a === cid) E.push(p + "after: a cell cannot depend on itself");
    }
    for (const x of slist(c, "supersedes")) {
      if (!ids.has(x)) E.push(p + `supersedes: unknown cell ${pyRepr(x)}`);
      else if (x === cid) E.push(p + "supersedes: a cell cannot supersede itself");
    }

    const allowed = slist(c, "allowed_paths");
    const outputs = slist(c, "outputs");
    if (outputs.length > cfg.max_cell_files) {
      E.push(p + `${outputs.length} outputs exceeds max_cell_files=${cfg.max_cell_files} (split the cell)`);
    }
    for (const o of outputs) {
      if (hasWild(o) || o.endsWith("/")) E.push(p + `output ${pyRepr(o)} must be a concrete file path`);
      else if (!matches(o, allowed)) E.push(p + `output ${pyRepr(o)} is not covered by allowed_paths`);
    }
    for (const ap of allowed) {
      const hit = protectedPaths.find((q) => mayOverlap(ap, q));
      if (hit) E.push(p + `allowed path ${pyRepr(ap)} touches protected path ${pyRepr(hit)}`);
    }
    for (const [glob, owner] of Object.entries(cfg.owners)) {
      if (!ids.has(owner)) E.push(`blueprint.yaml owners: ${pyRepr(glob)} is owned by unknown cell ${pyRepr(owner)}`);
      else if (cid !== owner && allowed.some((ap) => mayOverlap(ap, glob))) {
        E.push(p + `touches ${pyRepr(glob)}, which is owned by ${owner}`);
      }
    }
  }

  const sgraph: Record<string, string[]> = {};
  for (const [cid, c] of Object.entries(cells)) sgraph[cid] = slist(c, "supersedes").filter((x) => ids.has(x) && x !== cid);
  const scyc = Object.keys(sgraph).length ? findCycle(sgraph) : null;
  if (scyc) E.push("supersedes cycle: " + scyc.join(" -> "));
  const replaced = new Set<string>();
  for (const [a, targets] of Object.entries(sgraph)) {
    for (const b of targets) {
      replaced.add(`${a}|${b}`);
      replaced.add(`${b}|${a}`);
    }
  }

  const graph = hardGraph(cells);
  const cyc = Object.keys(graph).length ? findCycle(graph) : null;
  if (cyc) {
    E.push("dependency cycle: " + cyc.join(" -> "));
    return { errors: E, warnings: W };
  }

  const anc = ancestors(graph);
  const order = Object.keys(cells).sort();
  for (let ia = 0; ia < order.length; ia++) {
    for (let ib = ia + 1; ib < order.length; ib++) {
      const a = order[ia];
      const b = order[ib];
      if (anc[b].has(a) || anc[a].has(b)) continue; // ordered by dependencies: may share paths
      if (replaced.has(`${a}|${b}`)) continue; // one supersedes the other: they may share paths
      const hit = firstOverlap(slist(cells[a], "allowed_paths"), slist(cells[b], "allowed_paths"));
      if (hit) {
        E.push(
          `${a} and ${b} can run in parallel but their paths overlap: ${hit[0]} ~ ${hit[1]} ` +
            "(add an 'after' edge or split the paths)",
        );
      }
    }
  }

  const integrations = Object.entries(cells)
    .filter(([, c]) => c.type === "integration")
    .map(([i]) => i);
  for (const [cid, c] of Object.entries(cells)) {
    for (const i of inputsOf(c)) {
      if (i.kind === "contract" && ids.has(i.from)) {
        const prov = i.from as string;
        if (!integrations.some((x) => anc[x].has(cid) && anc[x].has(prov))) {
          W.push(
            `${cid} uses a contract of ${prov} but no integration cell depends on both ` +
              "(real wiring would go untested)",
          );
        }
      }
    }
  }

  const dd = directDependents(cells);
  const threshold = cfg.bottleneck_threshold ?? DEFAULTS.bottleneck_threshold;
  for (const cid of Object.keys(dd).sort()) {
    const n = dd[cid];
    if (n >= threshold && cells[cid].type !== "skeleton") {
      W.push(
        `${cid} is a bottleneck: ${n} cells wait for it to be merged. Turn some of those inputs into ` +
          "kind: contract, split it, or give it a short lease_minutes and top priority",
      );
    }
  }
  const sup = superseders(cells);
  for (const sid of Object.keys(sup).sort()) {
    const provided = new Set<string>();
    for (const x of sup[sid]) for (const l of slist(cells[x], "provides")) provided.add(l);
    for (const line of slist(cells[sid], "provides")) {
      if (!provided.has(line)) {
        W.push(`${sid}: superseded, but no superseder provides '${line}' (dependents may be left with a dangling contract)`);
      }
    }
  }
  return { errors: E, warnings: W };
}

/**
 * The cells a dependency d still waits for. Merged: none. Superseded and not merged: the superseders that are not
 * merged, each one followed down its own chain (a superseder that was itself replaced and never merged is left out
 * and its superseders count instead). Otherwise d itself.
 */
export function unmergedBlockers(d: string, sup: Record<string, string[]>, merged: Set<string>, seen: Set<string> = new Set()): string[] {
  if (merged.has(d) || seen.has(d)) return [];
  if (!(d in sup)) return [d];
  seen.add(d);
  return sup[d].flatMap((x) => unmergedBlockers(x, sup, merged, seen));
}

/** {superseded id: sorted ids of the cells that list it in `supersedes`} (known ids only, no self-reference). */
export function superseders(cells: Record<string, Cell>): Record<string, string[]> {
  const tmp: Record<string, Set<string>> = {};
  for (const [cid, c] of Object.entries(cells)) {
    for (const x of slist(c, "supersedes")) {
      if (x in cells && x !== cid) (tmp[x] ??= new Set()).add(cid);
    }
  }
  const out: Record<string, string[]> = {};
  for (const [k, v] of Object.entries(tmp)) out[k] = [...v].sort();
  return out;
}

function pyListRepr(xs: string[]): string {
  return "(" + xs.map(pyRepr).join(", ") + ")";
}

// ---------------------------------------------------------------- readiness
export function leaseOf(cell: Dict, dflt: number): number {
  return isPosInt(cell.lease_minutes) ? cell.lease_minutes : dflt;
}

export interface ReadyEntry {
  id: string;
  reclaim: boolean;
  critical: boolean;
  released: boolean;
}
export interface StateOptions {
  criticalChainThreshold?: number;
  criticalTransitiveThreshold?: number;
  criticalLeaseMinutes?: number;
  parkMaxMinutes?: number;
  released?: Iterable<string>;
  attempts?: Record<string, number>;
  maxAttempts?: number;
  feedback?: Iterable<string>;
}
export interface LockedEntry {
  id: string;
  minutes_left: number;
  ci?: boolean;
}
export interface WaitingEntry {
  id: string;
  blocked_by: string[];
}
export interface State {
  status: "all_done" | "ready" | "none_ready";
  ready: ReadyEntry[];
  locked: LockedEntry[];
  waiting: WaitingEntry[];
  needs_split?: { id: string; attempts: number }[];
  needs_human?: { id: string }[];
}

/**
 * Decide what can be started.
 * merged: merged cell ids. claims: minutes since the last commit on each cell's branch.
 * ci: minutes since the NEWEST still-active workflow run of each cell started.
 * A claimed cell stays locked while its commit lease is alive OR a workflow for it is active (at most
 * max_ci_minutes), so a chat that is only waiting for CI is not mistaken for one that ran out of tokens.
 * A cell is critical if it has >= bottleneckThreshold direct dependents, a chain of dependents of length
 * >= criticalChainThreshold (depth - 1), or >= criticalTransitiveThreshold dependents in all. A critical cell's
 * lease is at most criticalLeaseMinutes. released: ids of claimed cells whose branch tip is a release commit;
 * such a cell is expired at once (regardless of age and CI). Hand-out order: class 0 = expired critical or released;
 * class 1 = unclaimed, or expired non-critical at least parkMaxMinutes old; class 2 = younger expired
 * non-critical; then priority, depth, id.
 * attempts: how often each cell's lease died; feedback: ids with recorded human feedback. After the blockers
 * check: a cell in feedback is needs_human (any age); else a cell that would be handed out as a reclaim (lease
 * expired, not released) with attempts >= maxAttempts is needs_split. Both keys exist only when non-empty.
 * A cell listed in another cell's `supersedes` and not merged is left out of everything; a dependent waits for
 * the superseders instead (satisfied when all of them are merged).
 */
export function computeState(
  cells: Record<string, Cell>,
  merged: Iterable<string>,
  claims: Record<string, number>,
  leaseMinutes = 60,
  ci: Record<string, number> = {},
  maxCiMinutes = 45,
  bottleneckThreshold = 4,
  o: StateOptions = {},
): State {
  const criticalChainThreshold = o.criticalChainThreshold ?? 3;
  const criticalTransitiveThreshold = o.criticalTransitiveThreshold ?? 5;
  const criticalLeaseMinutes = o.criticalLeaseMinutes ?? 15;
  const parkMaxMinutes = o.parkMaxMinutes ?? 120;
  const releasedSet = new Set(o.released ?? []);
  const attempts = o.attempts ?? {};
  const maxAttempts = o.maxAttempts ?? 3;
  const feedbackSet = new Set(o.feedback ?? []);
  const mergedSet = new Set([...merged].filter((m) => m in cells));
  const sup = superseders(cells);
  const todo = Object.keys(cells).filter((c) => !mergedSet.has(c) && !(c in sup));
  if (todo.length === 0) return { status: "all_done", ready: [], locked: [], waiting: [] };

  const direct = directDependents(cells);
  const trans = transitiveDependents(cells);

  const graph = hardGraph(cells);
  const dependents: Record<string, string[]> = {};
  for (const c of Object.keys(cells)) dependents[c] = [];
  for (const [c, ds] of Object.entries(graph)) for (const d of ds) dependents[d].push(c);
  const depth: Record<string, number> = {};
  const dp = (n: string): number => {
    if (!(n in depth)) depth[n] = 1 + Math.max(0, ...dependents[n].map(dp));
    return depth[n];
  };
  const critical = (cid: string) =>
    direct[cid] >= bottleneckThreshold || dp(cid) - 1 >= criticalChainThreshold || trans[cid] >= criticalTransitiveThreshold;

  const ready: ReadyEntry[] = [];
  const locked: LockedEntry[] = [];
  const waiting: WaitingEntry[] = [];
  const needsSplit: { id: string; attempts: number }[] = [];
  const needsHuman: { id: string }[] = [];
  for (const cid of todo) {
    const blockers: string[] = [];
    for (const d of graph[cid]) {
      blockers.push(...unmergedBlockers(d, sup, mergedSet));
    }
    const blockedBy = [...new Set(blockers)];
    if (blockedBy.length) {
      waiting.push({ id: cid, blocked_by: blockedBy });
      continue;
    }
    if (feedbackSet.has(cid)) {
      needsHuman.push({ id: cid });
      continue;
    }
    const age = claims[cid];
    const crit = critical(cid);
    let lease = leaseOf(cells[cid], leaseMinutes);
    if (crit) lease = Math.min(lease, criticalLeaseMinutes);
    const rel = age !== undefined && releasedSet.has(cid);
    if (!rel && age !== undefined && age < lease) {
      locked.push({ id: cid, minutes_left: pyRound(lease - age) });
    } else if (!rel && age !== undefined && cid in ci && ci[cid] < maxCiMinutes) {
      locked.push({ id: cid, minutes_left: pyRound(maxCiMinutes - ci[cid]), ci: true });
    } else if (age !== undefined && !rel && (attempts[cid] ?? 0) >= maxAttempts) {
      needsSplit.push({ id: cid, attempts: attempts[cid] });
    } else {
      ready.push({ id: cid, reclaim: age !== undefined, critical: crit, released: rel });
    }
  }
  const orderClass = (r: ReadyEntry): number => {
    if (!r.reclaim) return 1;
    if (r.critical || r.released) return 0;
    return claims[r.id] >= parkMaxMinutes ? 1 : 2;
  };
  const prio = (id: string) => (Number.isInteger(cells[id].priority) ? (cells[id].priority as number) : 0) || 0;
  ready.sort((a, b) => {
    if (orderClass(a) !== orderClass(b)) return orderClass(a) - orderClass(b);
    if (prio(a.id) !== prio(b.id)) return prio(b.id) - prio(a.id);
    if (dp(a.id) !== dp(b.id)) return dp(b.id) - dp(a.id);
    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
  });
  const out: State = { status: ready.length ? "ready" : "none_ready", ready, locked, waiting };
  if (needsSplit.length) out.needs_split = needsSplit;
  if (needsHuman.length) out.needs_human = needsHuman;
  return out;
}

function needsLines(state: State): string[] {
  const lines: string[] = [];
  if (state.needs_split?.length) lines.push("needs_split: " + state.needs_split.map((x) => `${x.id}(${x.attempts} attempts)`).join(", "));
  if (state.needs_human?.length) lines.push("needs_human: " + state.needs_human.map((x) => x.id).join(", "));
  return lines;
}

/** Compact text for an agent: a few dozen tokens. */
export function render(state: State, maxWaiting = 8): string {
  if (state.status === "all_done") return "ALL_DONE: every cell is merged.";
  if (state.status === "ready") {
    const names = state.ready
      .map((r) => r.id + (r.critical ? "[critical]" : "") + (r.released ? "(released)" : r.reclaim ? "(expired-lease)" : ""))
      .join(" ");
    return [`READY ${names}`, "(take the first)", ...needsLines(state)].join("\n");
  }
  const lines = ["NONE_READY: no cell can be started now."];
  if (state.locked.length) {
    lines.push(
      "running: " +
        state.locked.map((x) => (x.ci ? `${x.id}(CI<=${x.minutes_left}m)` : `${x.id}(${x.minutes_left}m)`)).join(", "),
    );
  }
  const w = state.waiting;
  if (w.length) {
    const shown = w
      .slice(0, maxWaiting)
      .map((x) => `${x.id}<-${x.blocked_by.join(",")}`)
      .join("; ");
    lines.push("waiting: " + shown + (w.length > maxWaiting ? `; +${w.length - maxWaiting} more` : ""));
  }
  const nl = needsLines(state);
  lines.push(...nl);
  const onlyNeeds = nl.length > 0 && state.locked.length === 0 && w.length === 0;
  lines.push(onlyNeeds ? "A human must resolve the cells above." : "Wait for the running cells to merge, then ask again.");
  return lines.join("\n");
}

// ---------------------------------------------------------------- git-derived inputs
const ACTIVE_RUN = new Set(["queued", "in_progress", "waiting", "pending", "requested"]);

export interface RunInfo {
  status: string;
  headBranch?: string;
  displayTitle?: string;
  createdAt?: string;
}

/** {cell id: minutes since the NEWEST active run started}. The cell id comes from the head branch or from
 * the run title ("gate cell/C-NNN" / "preflight C-NNN", set with run-name: in the workflows). */
export function parseRuns(runs: RunInfo[], nowMs: number): Record<string, number> {
  const out: Record<string, number> = {};
  for (const r of runs || []) {
    if (!ACTIVE_RUN.has(r.status)) continue;
    const m = BRANCH_RE.exec(r.headBranch || "") || RUN_TITLE_RE.exec(r.displayTitle || "");
    if (!m) continue;
    const started = r.createdAt ? Date.parse(r.createdAt) : NaN;
    if (Number.isNaN(started)) continue;
    const age = Math.max(0, (nowMs - started) / 60000);
    const cid = m[1];
    out[cid] = cid in out ? Math.min(out[cid], age) : age;
  }
  return out;
}

export function mergedFromSubjects(subjects: string[]): Set<string> {
  const out = new Set<string>();
  for (const s of subjects) {
    const m = SUBJECT_RE.exec(s);
    if (m) out.add(m[1]);
  }
  return out;
}

export function claimsFromBranches(
  branches: Record<string, { committedDate: string }>,
  nowMs: number,
): Record<string, number> {
  const out: Record<string, number> = {};
  for (const [name, b] of Object.entries(branches)) {
    const m = BRANCH_RE.exec(name);
    const ts = Date.parse(b.committedDate);
    if (m && !Number.isNaN(ts)) out[m[1]] = Math.max(0, (nowMs - ts) / 60000);
  }
  return out;
}
